// Route contract for this endpoint (read by wf.gateway.auth).
const route = {"method": "PATCH", "template": "/v1/listings/:id", "require_user": true, "idempotent": true, "required_consents": ["terms", "privacy"], "roles": []};
const item = $input.first();
return [{ json: { ...item.json, t0: Date.now(), route }, binary: item.binary }];

// wf.api.listings_patch > "Validate body"   PATCH /v1/listings/:id (spec 2.4 journey B step 6, D-088)
// Body: the fields to change (rent, rent_period, deposit, bills_included, furnished, available_from, bedrooms,
// min_stay_months, place, amenities_add, amenities_remove, house_rules, remove_photos, status; amounts in the
// currency's main unit), checked in the database (app.listing_change_check); or {change_id} to apply a change the
// owner assistant proposed.
const gw = $input.first().json;
const id = (gw.ctx.params || {}).id || '';
const b = gw.ctx.body;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!UUID.test(id)) return [{ json: { ok: false, status: 404, gw, error: { code: 'NOT_FOUND', message: 'Listing not found', details: [] } } }];
const bad = (details) => [{ json: { ok: false, status: 422, gw, error: { code: 'VALIDATION_FAILED', message: 'Request body is invalid', details } } }];
if (!b || typeof b !== 'object' || Array.isArray(b) || !Object.keys(b).length) return bad([{ field: 'body', issue: 'no_change' }]);
if ('change_id' in b) {
  if (Object.keys(b).length > 1) return bad([{ field: 'change_id', issue: 'alone' }]);
  if (typeof b.change_id !== 'string' || !UUID.test(b.change_id)) return bad([{ field: 'change_id', issue: 'invalid_format' }]);
  return [{ json: { ok: true, gw, input: { user_id: gw.ctx.user_id, listing_id: id, change_id: b.change_id, changes: null } } }];
}
return [{ json: { ok: true, gw, input: { user_id: gw.ctx.user_id, listing_id: id, change_id: '', changes: b } } }];

// wf.api.listings_patch > "Build result": 200 with what changed; 404 for a listing that is not the caller's; 409 for a
// proposal that expired or was already decided; 422 with the field issues otherwise.
const gw = $('Validate body').first().json.gw;
const r = $input.first().json || {};
if (r.ok) {
  return [{ json: { ok: true, gw, status: 200, data: { listing_id: r.listing_id, status: r.status, diff: r.diff,
    publication: r.publication, photos_deleted_from_storage: r.photos_deleted_from_storage, embedded: r.embedded } } }];
}
const errors = Array.isArray(r.errors) ? r.errors : [];
if (r.found === false && !errors.some((e) => e.field === 'change_id')) {
  return [{ json: { ok: false, gw, status: 404, error: { code: 'NOT_FOUND', message: 'Listing not found', details: [] } } }];
}
const ch = errors.find((e) => e.field === 'change_id');
if (ch && ch.issue === 'not_found') return [{ json: { ok: false, gw, status: 404, error: { code: 'NOT_FOUND', message: 'Change not found', details: [ch] } } }];
if (ch) return [{ json: { ok: false, gw, status: 409, error: { code: 'CONFLICT', message: 'This change can no longer be applied', details: [ch] } } }];
return [{ json: { ok: false, gw, status: 422, error: { code: 'VALIDATION_FAILED', message: 'The change is invalid', details: errors } } }];

// Shared by every API workflow > "Envelope"
// Input: either a handler result {ok:true, status, data, gw} or a rejection
// from the gateway or a handler {ok:false, status, error | replay+response}.
// Output: {status, response, finish} where finish is the app.api_finish payload.
const x = $input.first().json;
const gw = x.gw || x;                       // handlers carry the gateway item in x.gw
const t0 = gw.t0 || Date.now();
const latency = Date.now() - t0;
const requestId = gw.request_id || (gw.ctx && gw.ctx.request_id) || null;
let status, response;
if (x.replay) {
  status = x.status;
  response = x.response;                    // stored response, returned unchanged
} else if (x.ok) {
  status = x.status || 200;
  response = { request_id: requestId, data: x.data ?? {}, meta: { latency_ms: latency, ...(x.meta || {}) } };
} else {
  status = x.status || 500;
  const e = x.error || { code: 'INTERNAL', message: 'Internal error', details: [] };
  response = { request_id: requestId, error: { code: e.code, message: e.message, details: e.details || [] } };
}
const finish = {
  request_id: requestId,
  workflow: $workflow.name,
  n8n_execution_id: String($execution.id),
  user_id: (gw.ctx && gw.ctx.user_id) || '',
  channel: 'api',
  status_code: status,
  latency_ms: latency,
  error_code: response && response.error ? response.error.code : null,
  idempotency: gw.idempotency || null,
  idempotency_replay: !!x.replay,
  response_body: response,
  result_user_id: x.result_user_id || null,
  // agent steps of the request (spec 8.3), written to ai.agent_steps with the execution
  steps: Array.isArray(x.steps) ? x.steps : [],
  // reason and detail go to ai.executions.error only, never to the client
  error_detail: x.log ? [x.log.reason, x.log.detail].filter(Boolean).join(': ').slice(0, 500) : null,
};
const headers = { 'X-Request-Id': requestId || '', 'Cache-Control': 'no-store' };
if (status === 429) {
  const d = (response.error && response.error.details || []).find((y) => y.retry_after_s);
  if (d) headers['Retry-After'] = String(d.retry_after_s);
}
return [{ json: { status, response, finish, headers } }];
